mapper.update:
UPDATE inv_balance
SET reserved = reserved - #{qty}, version = version + 1, updated_at = now()
WHERE  AND reserved >= #{qty}

mapper.select:
SELECT id, reserved_qty AS reservedQty, consumed_qty AS consumedQty,
       released_qty AS releasedQty, version
FROM inv_reservation
WHERE tenant_id = #{tenantId} AND source_doc_type = #{sourceDocType}
  AND source_doc_id = #{sourceDocId} AND source_line_id = #{sourceLineId}

